import { businessDate, type Clock, type EventBus, newId, systemClock } from "../kernel";
import type { Person, PersonRegistered, PersonRepository } from "./person";

export interface RegisterPersonInput {
  email: string;
  givenName: string;
  familyName: string;
  /** ISO date, `YYYY-MM-DD`. Not in the future. */
  dateOfBirth?: string;
  brand?: string;
}

export class EmailAlreadyRegisteredError extends Error {
  constructor() {
    super("A person with this e-mail exists");
    this.name = "EmailAlreadyRegisteredError";
  }
}

export class InvalidDateOfBirthError extends Error {
  constructor(reason: string) {
    super(`Invalid date of birth: ${reason}`);
    this.name = "InvalidDateOfBirthError";
  }
}

const ISO_DATE = /^\d{4}-\d{2}-\d{2}$/;

/** `true` when `value` is `YYYY-MM-DD` and names a day that exists in the calendar. */
function isCalendarDate(value: string): boolean {
  if (!ISO_DATE.test(value)) return false;
  const parsed = new Date(`${value}T00:00:00Z`);
  return !Number.isNaN(parsed.getTime()) && parsed.toISOString().slice(0, 10) === value;
}

/** Returns the date of birth to store, or throws when it is malformed or in the future. */
function validateDateOfBirth(value: string, today: string): string {
  if (!isCalendarDate(value)) throw new InvalidDateOfBirthError("expected YYYY-MM-DD");
  // ISO dates compare as strings.
  if (value > today) throw new InvalidDateOfBirthError("the date is in the future");
  return value;
}

export interface IdentityDeps {
  repo: PersonRepository;
  bus: EventBus;
  clock?: Clock;
}

export function createIdentity({ repo, bus, clock = systemClock }: IdentityDeps) {
  return {
    /** One person record per e-mail address (T3-D-009). */
    async registerPerson(input: RegisterPersonInput): Promise<Person> {
      const email = input.email.trim().toLowerCase();
      if (await repo.findByEmail(email)) throw new EmailAlreadyRegisteredError();
      const now = clock.now();
      const dateOfBirth =
        input.dateOfBirth === undefined
          ? null
          : validateDateOfBirth(input.dateOfBirth, businessDate(now));
      const person: Person = {
        id: newId(now),
        email,
        givenName: input.givenName,
        familyName: input.familyName,
        dateOfBirth,
        erpCustomerNumber: null,
        brand: input.brand ?? "provital",
        createdAt: now.toISOString(),
      };
      await repo.insert(person);
      const event: PersonRegistered = {
        type: "identity.person-registered",
        id: newId(now),
        occurredAt: now.toISOString(),
        payload: { personId: person.id, brand: person.brand },
      };
      await bus.publish(event);
      return person;
    },

    async getPerson(id: string): Promise<Person | null> {
      return repo.findById(id);
    },
  };
}

export type Identity = ReturnType<typeof createIdentity>;

